 void finish(String error){try{JSONObject observed=view.characterObservation();JSONObject out=new JSONObject();android.widget.Button support=HalfSwordViewCheck.button(view.controlsRoot(),stance?"Stance support setup":"Refreshed support setup");out.put("orbit_input_verified",orbitVerified).put("orbit_yaw_before",orbitBefore).put("orbit_yaw_after",orbitAfter);out.put("playtest_policy_version",1).put("support_control_enabled",support!=null&&support.isEnabled());out.put("support_control_present",HalfSwordViewCheck.button(view.controlsRoot(),stance?"Stance support setup":"Refreshed support setup")!=null);out.put("stance_support_applied",view.characterAppliedStanceSupport);out.put("refreshed_support_applied",view.characterAppliedRefreshedSupport);out.put("preset_control",stance?"Stance support setup":refreshed?"Refreshed support setup":"Ground-grip setup");out.put("held_observation",heldObservation).put("released_steps",releaseSteps).put("forced_frames_after_release",view.characterForcedFrames-releasedForced);org.json.JSONArray position=observed.optJSONArray("pelvis_cm");out.put("movement_distance_cm",position==null?JSONObject.NULL:Double.valueOf(Math.hypot(position.optDouble(0)-startX,position.optDouble(1)-startY)));out.put("passed",error==null).put("error",error==null?"":error).put("stage",stage).put("physics_steps",view.characterSteps).put("forced_frames",view.characterForcedFrames-forcedStart).put("observation",observed).put("movement_start_xy",new org.json.JSONArray(new double[]{startX,startY})).put("view_width",view.getWidth()).put("view_height",view.getHeight()).put("module",HalfSwordBridge.loadedModuleSha256).put("scene_monitor_error",view.sceneMonitorError).put("time_ms",System.currentTimeMillis());Payloads.writeSmall(result,out.toString());}catch(Exception failed){android.util.Log.e("Trough","Scene check result write failed",failed);}}
